var payout = new ApprovalRequiredAIFunction(AIFunctionFactory.Create(IssueRefund));

AIAgent agent = chatClient.AsHarnessAgent(new HarnessAgentOptions
{
    ChatOptions = new ChatOptions { Tools = [payout] },
    ToolApprovalAgentOptions = new ToolApprovalAgentOptions
    {
        AutoApprovalRules = [AgentSkillsProvider.ReadOnlyToolsAutoApprovalRule], // skill read tools only
    },
});
AgentSession session = await agent.CreateSessionAsync();
AgentResponse r = await agent.RunAsync("Refund order 42", session);

var req = r.Messages.SelectMany(m => m.Contents)
    .OfType<ToolApprovalRequestContent>().First();
var approve = new ChatMessage(ChatRole.User, [req.CreateResponse(true)]);
await agent.RunAsync(approve, session);   // same session

@tool(approval_mode='always_require')
def issue_refund(order_id: str) -> str:
    return f'refunded {order_id}'

agent = create_harness_agent(client=client, tools=issue_refund)
session = agent.create_session()          # required by approval middleware
result = await agent.run('Refund order 42', session=session)

while result.user_input_requests:
    replies = []
    for req in result.user_input_requests:
        ok = ask_human(req.function_call.name, req.function_call.arguments)
        replies.append(Message(role='user',
            contents=[req.to_function_approval_response(ok)]))
    result = await agent.run(replies, session=session)
